{"file_path":"src/policies.js","content":"/**
 * The two policy kinds a route can chain: token buckets and sliding
 * windows. Each keeps one independent state per key, keyed by the event
 * key string, and exposes the same three-step protocol the simulator
 * drives every policy through: advance to a tick, ask whether it allows,
 * and record an admitted request.
 */

/** A token bucket that refills by an exact fraction of a token per tick. */
export class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.max = capacity * per
    this.state = new Map()
  }

  advance(key, tick) {
    const s = this.state.get(key)
    if (!s) {
      this.state.set(key, { scaled: this.max, lastTick: tick })
      return
    }
    const elapsed = tick - s.lastTick
    if (elapsed > 0n) {
      let scaled = s.scaled + this.refill * elapsed
      if (scaled > this.max) scaled = this.max
      s.scaled = scaled
      s.lastTick = tick
    }
  }

  allow(key) {
    return this.state.get(key).scaled >= this.per
  }

  record(key) {
    const s = this.state.get(key)
    s.scaled -= this.per
  }
}

/** A sliding window that remembers the ticks it recorded for each key. */
export class SlidingWindow {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.state = new Map()
  }

  advance(key, tick) {
    let arr = this.state.get(key)
    if (!arr) {
      arr = []
      this.state.set(key, arr)
    }
    const threshold = tick - this.span
    let start = 0
    while (start < arr.length && arr[start] <= threshold) start++
    if (start > 0) arr.splice(0, start)
  }

  allow(key) {
    return BigInt(this.state.get(key).length) < this.limit
  }

  record(key, tick) {
    this.state.get(key).push(tick)
  }
}
"}

