{"file_path":"src/parser.js","content":"/**
 * Parses a limiter file into declared policies, routes and events, or
 * throws a ParseError carrying the one-based line number and reason the
 * CLI reports on standard error.
 */

import { TokenBucket, SlidingWindow } from './policies.js'

const NAME_RE = /^[A-Za-z0-9_.\/:-]+$/
const UINT_RE = /^(0|[1-9][0-9]*)$/

export class ParseError extends Error {
  constructor(line, reason) {
    super(reason)
    this.line = line
  }
}

function fail(line, reason) {
  throw new ParseError(line, reason)
}

function isValidName(token) {
  return NAME_RE.test(token)
}

function parseUint(token, field, least, line) {
  if (!UINT_RE.test(token)) fail(line, `${field} must be an integer of at least ${least}`)
  const value = BigInt(token)
  if (value < least) fail(line, `${field} must be an integer of at least ${least}`)
  return value
}

/**
 * Splits the raw file text into physical lines, dropping only the empty
 * tail a trailing newline leaves.
 */
function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

export function parse(text) {
  const policies = new Map()
  const routes = new Map()
  const events = []
  let seenEvent = false
  let lastTick = null

  const lines = splitLines(text)
  for (let i = 0; i < lines.length; i++) {
    const line = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]
    const rest = tokens.slice(1)

    if (directive === 'bucket') {
      if (seenEvent) fail(line, 'declarations must come before the first event')
      if (rest.length !== 4) fail(line, 'expected bucket <name> <capacity> <refill> <per>')
      const [name, capacityTok, refillTok, perTok] = rest
      if (!isValidName(name)) fail(line, `invalid policy name ${name}`)
      const capacity = parseUint(capacityTok, 'capacity', 1n, line)
      const refill = parseUint(refillTok, 'refill', 0n, line)
      const per = parseUint(perTok, 'per', 1n, line)
      if (policies.has(name)) fail(line, `policy ${name} is declared twice`)
      policies.set(name, new TokenBucket(capacity, refill, per))
    } else if (directive === 'window') {
      if (seenEvent) fail(line, 'declarations must come before the first event')
      if (rest.length !== 3) fail(line, 'expected window <name> <limit> <span>')
      const [name, limitTok, spanTok] = rest
      if (!isValidName(name)) fail(line, `invalid policy name ${name}`)
      const limit = parseUint(limitTok, 'limit', 0n, line)
      const span = parseUint(spanTok, 'span', 1n, line)
      if (policies.has(name)) fail(line, `policy ${name} is declared twice`)
      policies.set(name, new SlidingWindow(limit, span))
    } else if (directive === 'route') {
      if (seenEvent) fail(line, 'declarations must come before the first event')
      if (rest.length < 2) fail(line, 'expected route <prefix> <policy>...')
      const [prefix, ...policyNames] = rest
      if (!isValidName(prefix)) fail(line, `invalid route prefix ${prefix}`)
      for (const name of policyNames) {
        if (!policies.has(name)) fail(line, `unknown policy ${name}`)
      }
      if (routes.has(prefix)) fail(line, `prefix ${prefix} is routed twice`)
      routes.set(prefix, policyNames)
    } else if (directive === 'event') {
      if (rest.length !== 2) fail(line, 'expected event <tick> <key>')
      const [tickTok, key] = rest
      const tick = parseUint(tickTok, 'tick', 0n, line)
      if (!isValidName(key)) fail(line, `invalid key ${key}`)
      if (lastTick !== null && tick < lastTick) fail(line, `tick ${tick} is before tick ${lastTick}`)
      lastTick = tick
      seenEvent = true
      events.push({ tick, key })
    } else {
      fail(line, `unknown directive ${directive}`)
    }
  }

  return { policies, routes, events }
}
"}

