{"file_path":"src/simulate.js","content":"/**
 * Replays parsed events through the routes and policies they resolve to,
 * producing a verdict per event and running per-key and total tallies.
 */

function findRoute(key, routes) {
  let best = null
  for (const [prefix, policyNames] of routes) {
    if (key.startsWith(prefix) && (best === null || prefix.length > best.prefix.length)) {
      best = { prefix, policyNames }
    }
  }
  return best
}

